  madsb_form_title: ["Instant form", "მყისიერი ფორმა", "Моментальная форма", "Anında form", "نموذج فوري", "טופס מיידי"],
  madsb_form_existing: ["Existing form on your Page", "არსებული ფორმა თქვენს გვერდზე", "Существующая форма на вашей странице", "Sayfanızdaki mevcut form", "نموذج موجود على صفحتك", "טופס קיים בעמוד שלכם"],
